(()=>{"use strict";const input=document.querySelector("#faq-search-input");const form=document.querySelector(".faq-search");if(!input||!form)return;const items=Array.from(document.querySelectorAll("[data-faq-item]"));const chapters=Array.from(document.querySelectorAll("[data-faq-chapter]"));const status=document.querySelector("[data-faq-status]");const empty=document.querySelector("[data-faq-empty]");const clear=document.querySelector("[data-faq-clear]");const normalize=value=>value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();const searchText=new Map(items.map(item=>[item,normalize(item.textContent)]));let previousOpen=null;let timer;document.querySelector("[data-faq-search-area]").hidden=false;function filter(){const query=normalize(input.value.trim());const terms=query.split(/\s+/).filter(Boolean);if(query&&!previousOpen)previousOpen=new Map(items.map(item=>[item,item.open]));let count=0;items.forEach(item=>{const match=terms.every(term=>searchText.get(item).includes(term));item.hidden=!match;if(match)count++;if(query)item.open=match;else if(previousOpen)item.open=previousOpen.get(item)});if(!query)previousOpen=null;chapters.forEach(chapter=>{chapter.hidden=!Array.from(chapter.querySelectorAll("[data-faq-item]")).some(item=>!item.hidden)});clear.hidden=!query;empty.hidden=count!==0;status.textContent=query?count+(count===1?" resposta encontrada.":" respostas encontradas."):items.length+" respostas organizadas por tema."}function reset(focusInput=false){clearTimeout(timer);input.value="";filter();if(focusInput)input.focus({preventScroll:true})}form.addEventListener("submit",event=>{event.preventDefault();clearTimeout(timer);filter()});input.addEventListener("input",()=>{clearTimeout(timer);timer=setTimeout(filter,140)});input.addEventListener("search",filter);clear.addEventListener("click",()=>reset(true));document.querySelector("[data-faq-reset]").addEventListener("click",()=>reset(true));function showLinkedQuestion(hash,scroll=false){let id;try{id=decodeURIComponent(hash.slice(1))}catch(_){return}const target=document.getElementById(id);if(!target||!target.matches("[data-faq-item]")&&!target.matches("[data-faq-chapter]"))return;if(input.value)reset();if(target.matches("[data-faq-item]"))target.open=true;if(scroll)requestAnimationFrame(()=>target.scrollIntoView({block:"start",behavior:"auto"}))}document.addEventListener("click",event=>{const link=event.target.closest('a[href^="#"]');if(!link||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;showLinkedQuestion(link.getAttribute("href"))});window.addEventListener("hashchange",()=>showLinkedQuestion(window.location.hash,true));if(window.location.hash)showLinkedQuestion(window.location.hash,true)})();